(() => {
  // 自动定位主酒馆窗口（兼容 iframe 沙箱）
  let W = window;
  try { while (!W.document.getElementById('chat') && W !== W.parent) W = W.parent; } catch (e) {}
  const D = W.document;
  W.__ncm?.();

  const LS = 'ncm_player_v1';
  const load = () => { try { return JSON.parse(W.localStorage.getItem(LS)) || {}; } catch (e) { return {}; } };
  const save = (o) => { try { W.localStorage.setItem(LS, JSON.stringify(o)); } catch (e) {} };
  let st = load();

  D.getElementById('ncm-style')?.remove();
  const css = D.createElement('style');
  css.id = 'ncm-style';
  css.textContent = `
    #ncm-fab{position:fixed;z-index:99998;width:44px;height:44px;border-radius:50%;display:flex;align-items:center;justify-content:center;
      font-size:21px;cursor:pointer;user-select:none;color:#fff;background:linear-gradient(135deg,#ff5b5e,#c9162b);
      box-shadow:0 6px 18px rgba(0,0,0,.35);touch-action:none;transition:transform .15s;}
    #ncm-fab:active{transform:scale(.92);}
    #ncm-panel{position:fixed;z-index:99999;width:344px;max-width:92vw;border-radius:14px;overflow:hidden;display:none;
      background-color:#1f1f23;color:#e8e8e8;border:1px solid rgba(127,127,127,.25);box-shadow:0 12px 40px rgba(0,0,0,.5);
      font-family:"LXGW WenKai","Kaiti SC","STKaiti",sans-serif;}
    #ncm-panel.show{display:block;animation:ncmIn .2s ease;}
    @keyframes ncmIn{from{opacity:0;transform:translateY(6px);}to{opacity:1;transform:none;}}
    .ncm-bar{display:flex;gap:6px;padding:8px;background:rgba(0,0,0,.18);align-items:center;}
    .ncm-bar input{flex:1;min-width:0;padding:6px 8px;border-radius:8px;border:1px solid rgba(127,127,127,.3);background:rgba(255,255,255,.07);color:#eee;font-size:12px;outline:none;}
    .ncm-bar select{padding:6px 4px;border-radius:8px;border:1px solid rgba(127,127,127,.3);background:#2a2a30;color:#eee;font-size:12px;}
    .ncm-bar button{padding:6px 10px;border:none;border-radius:8px;cursor:pointer;font-size:12px;background:#c9162b;color:#fff;white-space:nowrap;}
    .ncm-bar .ncm-x{background:rgba(127,127,127,.3);padding:6px 9px;}
    #ncm-frame{width:100%;height:452px;border:0;display:block;background:#fff;}
    .ncm-empty{padding:22px 16px;color:#aaa;font-size:12px;line-height:1.8;text-align:center;}
    .ncm-empty b{color:#ddd;}`;
  D.head.appendChild(css);

  const fab = D.createElement('div'); fab.id = 'ncm-fab'; fab.textContent = '♪'; D.body.appendChild(fab);
  const panel = D.createElement('div'); panel.id = 'ncm-panel'; D.body.appendChild(panel);

  fab.style.left = (st.fx ?? (W.innerWidth - 60)) + 'px';
  fab.style.top = (st.fy ?? (W.innerHeight - 150)) + 'px';

  const idFromInput = (v) => {
    v = (v || '').trim();
    const m = v.match(/(?:id=|playlist\/|song\/)(\d{3,})/i) || v.match(/^(\d{3,})$/);
    return m ? m[1] : '';
  };

  const renderPanel = () => {
    const type = st.type || '0', id = st.id || '';
    panel.innerHTML = `
      <div class='ncm-bar'>
        <input id='ncm-input' placeholder='粘贴歌单链接或ID' value='${id}'>
        <select id='ncm-type'><option value='0'>歌单</option><option value='2'>单曲</option></select>
        <button id='ncm-go'>载入</button>
        <button class='ncm-x' id='ncm-close'>×</button>
      </div>` + (id
        ? `<iframe id='ncm-frame' frameborder='no' allow='autoplay' src='//music.163.com/outchain/player?type=${type}&id=${id}&auto=0&height=430'></iframe>`
        : `<div class='ncm-empty'>输入你的歌单ID或分享链接后点「载入」。<br>歌单需为 <b>公开</b> 歌单（私密歌单外链无法播放）。<br>App/电脑里「分享 → 复制链接」粘贴即可。</div>`);
    const ty = panel.querySelector('#ncm-type'); if (ty) ty.value = type;
    panel.querySelector('#ncm-close').onclick = () => togglePanel(false);
    panel.querySelector('#ncm-go').onclick = () => {
      const inp = panel.querySelector('#ncm-input');
      const nid = idFromInput(inp.value);
      if (!nid) { inp.value = ''; inp.placeholder = '没识别到ID，请检查链接'; return; }
      st.id = nid; st.type = panel.querySelector('#ncm-type').value; save(st); renderPanel();
    };
  };

  const placePanel = () => {
    const r = fab.getBoundingClientRect();
    let left = Math.max(8, Math.min(r.left, W.innerWidth - 344 - 8));
    let top = r.top - 462; if (top < 8) top = Math.min(r.bottom + 8, W.innerHeight - 470);
    panel.style.left = left + 'px'; panel.style.top = Math.max(8, top) + 'px';
  };
  const togglePanel = (show) => {
    const willShow = show ?? !panel.classList.contains('show');
    if (willShow) { renderPanel(); placePanel(); panel.classList.add('show'); }
    else panel.classList.remove('show');
    st.open = willShow; save(st);
  };

  let drag = null;
  const down = (e) => { const p = e.touches ? e.touches[0] : e; drag = { x: p.clientX, y: p.clientY, l: fab.offsetLeft, t: fab.offsetTop, moved: false }; };
  const move = (e) => {
    if (!drag) return; const p = e.touches ? e.touches[0] : e;
    const dx = p.clientX - drag.x, dy = p.clientY - drag.y;
    if (Math.abs(dx) + Math.abs(dy) > 4) drag.moved = true;
    fab.style.left = Math.max(4, Math.min(drag.l + dx, W.innerWidth - 48)) + 'px';
    fab.style.top = Math.max(4, Math.min(drag.t + dy, W.innerHeight - 48)) + 'px';
    if (panel.classList.contains('show')) placePanel();
    if (drag.moved) e.preventDefault();
  };
  const up = () => { if (!drag) return; if (!drag.moved) togglePanel(); else { st.fx = fab.offsetLeft; st.fy = fab.offsetTop; save(st); } drag = null; };
  fab.addEventListener('mousedown', down); D.addEventListener('mousemove', move); D.addEventListener('mouseup', up);
  fab.addEventListener('touchstart', down, { passive: false }); D.addEventListener('touchmove', move, { passive: false }); D.addEventListener('touchend', up);
  W.addEventListener('resize', () => { if (panel.classList.contains('show')) placePanel(); });

  if (st.open && st.id) togglePanel(true);

  W.__ncm = () => { fab.remove(); panel.remove(); css.remove(); D.removeEventListener('mousemove', move); D.removeEventListener('mouseup', up); D.removeEventListener('touchmove', move); D.removeEventListener('touchend', up); };
})();
